//! The shell's skin: the browser editor's elements as measured, in paint
//! order (skin_data.rs, generated by tools/make_skin.py). Each entry has the
//! condition under which it shows and how its rectangle follows the window.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Kind {
    Rect,
    Image,
    Text,
    Hit,
    Control,
}

pub struct Entry {
    pub kind: Kind,
    /// Ribbon tab it shows on, -1 for every tab.
    pub tab: i32,
    /// Open menu it belongs to (9: the file panel), -1 for none.
    pub opened: i32,
    /// Bit per menu that hides it while open.
    pub closed: u32,
    /// 0: only with an empty history, 1: only with a filled one, -1: always.
    pub history: i32,
    /// History row template (0: newest, 1: the others), -1 for none.
    pub row: i32,
    pub tool: &'static str,
    pub swatch: &'static str,
    /// How x, w follow the width and y, h the height.
    pub k: [f64; 4],
    /// The rectangle measured at 1440 × 940.
    pub r: [f64; 4],
    pub image: i32,
    pub face: usize,
    pub size: i32,
    pub color: [u8; 4],
    pub spacing: i32,
    pub align: i32,
    pub text: &'static str,
    pub action: &'static str,
}

pub const MEASURED_WIDTH: f64 = 1440.0;
pub const MEASURED_HEIGHT: f64 = 940.0;

pub struct State<'a> {
    pub tab: i32,
    pub opened: i32,
    pub filled: bool,
    pub tool: &'a str,
    pub swatch: &'a str,
}

fn admits(wanted: &str, current: &str) -> bool {
    match wanted.strip_prefix('!') {
        _ if wanted.is_empty() => true,
        Some(not) => not != current,
        None => wanted == current,
    }
}

#[derive(Clone, Copy, Debug)]
pub struct Box {
    pub x: i32,
    pub y: i32,
    pub w: i32,
    pub h: i32,
    pub left: f64,
    pub top: f64,
}

impl Box {
    pub fn contains(&self, x: i32, y: i32) -> bool {
        x >= self.x && y >= self.y && x < self.x + self.w && y < self.y + self.h
    }
}

impl Entry {
    /// Whether it shows in the state; row templates show only through the
    /// history list.
    pub fn shows(&self, state: &State) -> bool {
        if self.tab >= 0 && self.tab != state.tab {
            return false;
        }
        if self.opened >= 0 && self.opened != state.opened {
            return false;
        }
        if state.opened >= 0 && state.opened < 32 && (self.closed >> state.opened) & 1 == 1 {
            return false;
        }
        if (self.history == 0 && state.filled) || (self.history == 1 && !state.filled) || self.row >= 0 {
            return false;
        }
        admits(self.tool, state.tool) && admits(self.swatch, state.swatch)
    }

    /// The measured rectangle moved and stretched with the window.
    pub fn place(&self, width: i32, height: i32) -> Box {
        let dx = width as f64 - MEASURED_WIDTH;
        let dy = height as f64 - MEASURED_HEIGHT;
        let left = self.r[0] + self.k[0] * dx;
        let top = self.r[1] + self.k[2] * dy;
        let right = left + self.r[2] + self.k[1] * dx;
        let bottom = top + self.r[3] + self.k[3] * dy;
        let (x, y) = (left.round() as i32, top.round() as i32);
        Box { x, y, w: right.round() as i32 - x, h: bottom.round() as i32 - y, left, top }
    }

    pub fn color(&self) -> crate::canvas::Color {
        let [r, g, b, a] = self.color;
        crate::canvas::Color { r, g, b, a }
    }
}
